#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <errno.h>
#include <limits.h>

#define MAX_CHUNK_SIZE 4096
#define MAX_TOTAL_SIZE (1024 * 1024)
#define HEADER_MAGIC 0xDEADBEEF
#define MAX_CHUNKS 256

typedef struct {
    uint32_t magic;
    uint16_t version;
    uint16_t num_chunks;
    uint32_t total_length;
    uint32_t checksum;
} __attribute__((packed)) FileHeader;

typedef struct {
    uint16_t chunk_id;
    int16_t  data_length;  /* signed for delta-encoding support */
    uint32_t offset;
    uint8_t  flags;
    uint8_t  reserved[3];
} __attribute__((packed)) ChunkDescriptor;

typedef struct {
    uint8_t *buffer;
    size_t   capacity;
    size_t   used;
} OutputBuffer;

static uint32_t compute_checksum(const uint8_t *data, size_t len) {
    uint32_t sum = 0;
    for (size_t i = 0; i < len; i++) {
        sum = ((sum << 5) + sum) + data[i];
    }
    return sum;
}

static int validate_header(const FileHeader *hdr) {
    if (hdr->magic != HEADER_MAGIC) {
        fprintf(stderr, "Invalid magic: 0x%08X\n", hdr->magic);
        return -1;
    }
    if (hdr->version < 1 || hdr->version > 3) {
        fprintf(stderr, "Unsupported version: %u\n", hdr->version);
        return -1;
    }
    if (hdr->num_chunks == 0 || hdr->num_chunks > MAX_CHUNKS) {
        fprintf(stderr, "Invalid chunk count: %u\n", hdr->num_chunks);
        return -1;
    }
    if (hdr->total_length > MAX_TOTAL_SIZE) {
        fprintf(stderr, "Total length exceeds maximum: %u\n", hdr->total_length);
        return -1;
    }
    return 0;
}

static int validate_chunk_descriptor(const ChunkDescriptor *desc, 
                                      uint32_t total_length,
                                      int chunk_index) {
    /* Validate chunk_id matches expected sequence */
    if (desc->chunk_id != (uint16_t)chunk_index) {
        fprintf(stderr, "Chunk ID mismatch: expected %d, got %u\n", 
                chunk_index, desc->chunk_id);
        return -1;
    }

    /* Validate data_length is within bounds */
    /* For delta-encoded chunks (flag 0x01), data_length can be negative
       indicating a reference to a previous chunk's data with offset */
    if (desc->flags & 0x01) {
        /* Delta chunk: data_length is a signed offset, absolute value must be valid */
        int16_t abs_len = desc->data_length < 0 ? -desc->data_length : desc->data_length;
        if (abs_len > MAX_CHUNK_SIZE) {
            fprintf(stderr, "Delta chunk %d: abs length %d exceeds max\n", 
                    chunk_index, abs_len);
            return -1;
        }
    } else {
        /* Regular chunk: data_length must be positive and bounded */
        if (desc->data_length <= 0 || desc->data_length > MAX_CHUNK_SIZE) {
            fprintf(stderr, "Chunk %d: invalid length %d\n", 
                    chunk_index, desc->data_length);
            return -1;
        }
    }

    /* Validate offset is within total file bounds */
    if (desc->offset >= total_length) {
        fprintf(stderr, "Chunk %d: offset %u beyond total length %u\n",
                chunk_index, desc->offset, total_length);
        return -1;
    }

    return 0;
}

static int extract_chunk_data(const uint8_t *file_data, size_t file_size,
                              const ChunkDescriptor *desc,
                              OutputBuffer *output) {
    size_t copy_offset = desc->offset;
    int16_t raw_length = desc->data_length;
    uint16_t length;

    if (desc->flags & 0x01) {
        /* Delta chunk: use absolute value of data_length */
        length = (uint16_t)(raw_length < 0 ? -raw_length : raw_length);
    } else {
        /* Regular chunk: already validated as positive in validate_chunk_descriptor */
        length = (uint16_t)raw_length;
    }

    /* 
     * Security check: ensure we don't read beyond file boundaries.
     * Cast length to size_t (always non-negative since it's uint16_t).
     */
    size_t safe_length = (size_t)length;
    if (safe_length == 0) {
        fprintf(stderr, "Zero-length chunk rejected\n");
        return -1;
    }

    if (copy_offset > file_size || safe_length > file_size - copy_offset) {
        fprintf(stderr, "Chunk read would exceed file boundary\n");
        return -1;
    }

    /* Ensure output buffer has space */
    if (safe_length > output->capacity - output->used) {
        fprintf(stderr, "Output buffer overflow prevented\n");
        return -1;
    }

    memcpy(output->buffer + output->used, file_data + copy_offset, safe_length);
    output->used += safe_length;

    return 0;
}

int process_file(const uint8_t *file_data, size_t file_size,
                 uint8_t **out_data, size_t *out_size) {
    if (file_size < sizeof(FileHeader)) {
        fprintf(stderr, "File too small for header\n");
        return -1;
    }

    const FileHeader *hdr = (const FileHeader *)file_data;

    if (validate_header(hdr) != 0) {
        return -1;
    }

    /* Verify checksum over the data portion */
    size_t data_start = sizeof(FileHeader) + 
                        (size_t)hdr->num_chunks * sizeof(ChunkDescriptor);
    if (data_start > file_size) {
        fprintf(stderr, "File too small for chunk descriptors\n");
        return -1;
    }

    uint32_t computed_checksum = compute_checksum(file_data + data_start, 
                                                  file_size - data_start);
    if (computed_checksum != hdr->checksum) {
        fprintf(stderr, "Checksum mismatch: expected 0x%08X, got 0x%08X\n",
                hdr->checksum, computed_checksum);
        return -1;
    }

    /* Parse and validate all chunk descriptors first */
    const ChunkDescriptor *descriptors = 
        (const ChunkDescriptor *)(file_data + sizeof(FileHeader));

    for (int i = 0; i < hdr->num_chunks; i++) {
        if (validate_chunk_descriptor(&descriptors[i], hdr->total_length, i) != 0) {
            return -1;
        }
    }

    /* Allocate output buffer */
    OutputBuffer output;
    output.capacity = MAX_TOTAL_SIZE;
    output.buffer = (uint8_t *)malloc(output.capacity);
    if (!output.buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }
    output.used = 0;

    /* Extract data from each chunk */
    for (int i = 0; i < hdr->num_chunks; i++) {
        if (extract_chunk_data(file_data, file_size, &descriptors[i], &output) != 0) {
            free(output.buffer);
            return -1;
        }
    }

    *out_data = output.buffer;
    *out_size = output.used;
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <input_file>\n", argv[0]);
        return 1;
    }

    FILE *fp = fopen(argv[1], "rb");
    if (!fp) {
        fprintf(stderr, "Cannot open file: %s\n", strerror(errno));
        return 1;
    }

    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize <= 0 || fsize > 10 * 1024 * 1024) {
        fprintf(stderr, "Invalid file size\n");
        fclose(fp);
        return 1;
    }
    fseek(fp, 0, SEEK_SET);

    uint8_t *file_data = (uint8_t *)malloc((size_t)fsize);
    if (!file_data) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(fp);
        return 1;
    }

    if (fread(file_data, 1, (size_t)fsize, fp) != (size_t)fsize) {
        fprintf(stderr, "Read error\n");
        free(file_data);
        fclose(fp);
        return 1;
    }
    fclose(fp);

    uint8_t *out_data = NULL;
    size_t out_size = 0;

    int result = process_file(file_data, (size_t)fsize, &out_data, &out_size);

    if (result == 0) {
        printf("Successfully processed %zu bytes of output\n", out_size);
        /* Write output or process further... */
        free(out_data);
    }

    free(file_data);
    return result == 0 ? 0 : 1;
}
